using Xunit;
using ReviveOS.Core;
using ReviveOS.TurboEngine;
using ReviveOS.ProcessManager;
using ReviveOS.Diagnostics;
public class ContinuousTests {
 static ResourceSample Sample(double? cpu=95,long ram=700,double? disk=0,bool? battery=false,double? overhead=0,double ownRam=40)=>new(DateTime.UtcNow,cpu,ram,3072,disk,battery,overhead,ownRam);
 static ContinuousDecision Three(ContinuousPolicy policy,ResourceSample sample,ContinuousConfig? config=null){ContinuousDecision? result=null;for(int i=0;i<3;i++)result=policy.Evaluate(sample,config??new());return result!;}
 [Fact] public void RequiresSustainedPressureAndRestoresWithHysteresis(){var policy=new ContinuousPolicy();Assert.False(policy.Evaluate(Sample(),new()).BoostForeground);Assert.False(policy.Evaluate(Sample(),new()).BoostForeground);Assert.True(policy.Evaluate(Sample(),new()).BoostForeground);Assert.True(policy.Evaluate(Sample(cpu:40),new()).CpuPressure);Assert.False(Three(policy,Sample(cpu:40)).CpuPressure);}
 [Fact] public void DiskPressureAndLowMemoryPreventForegroundBoost(){var disk=Three(new(),Sample(disk:3));Assert.True(disk.DiskPressure);Assert.False(disk.BoostForeground);Assert.True(disk.DeferOwnBackup);Assert.False(Three(new(),Sample(ram:100)).BoostForeground);Assert.False(Three(new(),Sample(battery:true)).BoostForeground);Assert.False(Three(new(),Sample(battery:null)).BoostForeground);}
 [Fact] public void AgentBudgetCausesPassiveMode(){var result=Three(new(),Sample(overhead:4));Assert.True(result.ResourceBudgetLimited);Assert.False(result.BoostForeground);Assert.False(result.LowerApprovedBackground);Assert.True(Three(new(),Sample(ownRam:100)).ResourceBudgetLimited);}
 [Fact] public void UnknownCountersDoNotPretendPressure(){var result=Three(new(),Sample(cpu:null,disk:null));Assert.False(result.CpuPressure);Assert.False(result.BoostForeground);Assert.False(result.DiskPressure);}
 [Fact] public void BackgroundChangesRequireExplicitExecutableAllowlist(){new ContinuousConfig{ApprovedBackgroundPaths=[]}.Validate();Assert.Throws<ArgumentException>(()=>new ContinuousConfig{ApprovedBackgroundPaths=[Path.GetFullPath("Defender.exe")]}.Validate());Assert.Throws<ArgumentException>(()=>new ContinuousConfig{PollSeconds=1}.Validate());Assert.Throws<ArgumentException>(()=>new ContinuousConfig{ApprovedBackgroundPaths=["Discord.exe"]}.Validate());}
 sealed class Fake:IPriorityBackend {public ProcessDescriptor? Current=new(new(123,456,"/app/chrome.exe","sid",1),NativePriorityBackend.Normal,0);public bool Fail;public int Changes;public ProcessDescriptor? Describe(int pid)=>Current;public void Change(ProcessIdentity identity,uint expected,uint target){if(Fail)throw new IOException("access denied");Assert.NotNull(Current);Assert.True(NativePriorityBackend.Same(identity,Current.Identity));Assert.Equal(expected,Current.Priority);Current=Current with{Priority=target};Changes++;}}
 static string FilePath()=>Path.Combine(Path.GetTempPath(),"revive-test-"+Guid.NewGuid(),"priorities.json");
 [Fact] public void PriorityChangeHasDurableRecoveryAcrossSessions(){var file=FilePath();try{var backend=new Fake();new PrioritySession(file,backend).Apply(backend.Current!,NativePriorityBackend.AboveNormal);Assert.Equal(NativePriorityBackend.AboveNormal,backend.Current!.Priority);new PrioritySession(file,backend).Restore();Assert.Equal(NativePriorityBackend.Normal,backend.Current.Priority);Assert.Equal(2,backend.Changes);}finally{Directory.Delete(Path.GetDirectoryName(file)!,true);}}
 [Fact] public void PidReuseIsNeverRestoredIntoDifferentProcess(){var file=FilePath();try{var backend=new Fake();var journal=new PrioritySession(file,backend);journal.Apply(backend.Current!,NativePriorityBackend.AboveNormal);backend.Current=backend.Current! with{Identity=backend.Current.Identity with{CreationTime=999}};journal.Restore();Assert.Equal(1,backend.Changes);Assert.Equal("exited-or-reused",journal.Entries().Single().State);}finally{Directory.Delete(Path.GetDirectoryName(file)!,true);}}
 [Fact] public void ExternalPriorityChangeIsPreserved(){var file=FilePath();try{var backend=new Fake();var journal=new PrioritySession(file,backend);journal.Apply(backend.Current!,NativePriorityBackend.AboveNormal);backend.Current=backend.Current! with{Priority=NativePriorityBackend.BelowNormal};journal.Restore();Assert.Equal(1,backend.Changes);Assert.Equal("external-change",journal.Entries().Single().State);}finally{Directory.Delete(Path.GetDirectoryName(file)!,true);}}
 [Fact] public void FailedApplyIsJournaledBeforeMutation(){var file=FilePath();try{var backend=new Fake{Fail=true};var journal=new PrioritySession(file,backend);Assert.Throws<IOException>(()=>journal.Apply(backend.Current!,NativePriorityBackend.AboveNormal));Assert.Equal("pending",journal.Entries().Single().State);backend.Fail=false;journal.Restore();Assert.Equal(NativePriorityBackend.Normal,backend.Current!.Priority);}finally{Directory.Delete(Path.GetDirectoryName(file)!,true);}}
 [Fact] public void FailedRollbackIsRetainedForRetry(){var file=FilePath();try{var backend=new Fake();var journal=new PrioritySession(file,backend);journal.Apply(backend.Current!,NativePriorityBackend.AboveNormal);backend.Fail=true;journal.Restore();Assert.Equal("restore-failed",journal.Entries().Single().State);backend.Fail=false;journal.Restore();Assert.Equal(NativePriorityBackend.Normal,backend.Current!.Priority);}finally{Directory.Delete(Path.GetDirectoryName(file)!,true);}}
 [WindowsFact] public async Task NativeCountersReturnMeasuredCpuAndRam(){using var sampler=new NativeResourceSampler();Assert.Null(sampler.Read().CpuPercent);await Task.Delay(1100);var sample=sampler.Read();Assert.NotNull(sample.CpuPercent);Assert.InRange(sample.CpuPercent!.Value,0,100);Assert.True(sample.TotalMemoryMB>0);Assert.InRange(sample.AvailableMemoryMB,0,sample.TotalMemoryMB);}
 [WindowsFact] public async Task RealChildPriorityIsChangedAndRestored(){if(!OperatingSystem.IsWindows())throw new PlatformNotSupportedException();var fixture=Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"../../../../ReviveOS.PriorityFixture/bin/Release/net8.0/ReviveOS.PriorityFixture.dll"));Assert.True(File.Exists(fixture));using var child=System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("dotnet"){ArgumentList={fixture},UseShellExecute=false,CreateNoWindow=true})!;var file=FilePath();try{await Task.Delay(500);Assert.False(child.HasExited);var backend=new NativePriorityBackend();var descriptor=backend.Describe(child.Id)!;Assert.Equal(NativePriorityBackend.Normal,descriptor.Priority);var journal=new PrioritySession(file,backend);journal.Apply(descriptor,NativePriorityBackend.AboveNormal);Assert.Equal(NativePriorityBackend.AboveNormal,backend.Describe(child.Id)!.Priority);journal.Restore();Assert.Equal(NativePriorityBackend.Normal,backend.Describe(child.Id)!.Priority);}finally{if(!child.HasExited){child.Kill();await child.WaitForExitAsync();}if(Directory.Exists(Path.GetDirectoryName(file)))Directory.Delete(Path.GetDirectoryName(file)!,true);}}
}
